{
  "information_kinds": [
    {
      "name": "patient_identity",
      "description": "Names, dates of birth, MRNs, and contact details used to identify and verify the patient."
    },
    {
      "name": "care_team_assignment",
      "description": "Facts about which staff members are assigned to or responsible for the patient, such as assigned_clinician."
    },
    {
      "name": "clinical_notes",
      "description": "Narrative clinical observations, assessments, care plans, and treatment discussions."
    },
    {
      "name": "diagnoses",
      "description": "Confirmed or suspected medical conditions, problem lists, and diagnostic conclusions."
    },
    {
      "name": "medications",
      "description": "Prescriptions, medication orders, dosing, allergies, and medication-related safety information."
    },
    {
      "name": "lab_results",
      "description": "Test orders, specimen details, and laboratory or diagnostic test results."
    },
    {
      "name": "appointments",
      "description": "Visit times, locations, reminders, and scheduling status."
    },
    {
      "name": "billing",
      "description": "Invoices, insurance details, payments, claims, and service-date information needed for billing."
    },
    {
      "name": "consent",
      "description": "Explicit owner consent or revocation for access to, or sharing of, specific patient details."
    },
    {
      "name": "family_contact",
      "description": "Family members, next of kin, and contact or communication preferences for family."
    },
    {
      "name": "social_context",
      "description": "Social determinants, housing, employment, support needs, and social-work assessments."
    },
    {
      "name": "summary",
      "description": "High-level, non-sensitive summaries suitable for limited or family access."
    }
  ],
  "roles": [
    {
      "role": "billing",
      "kinds": [
        "patient_identity",
        "billing"
      ],
      "reason": "Billing staff need enough identity to match the patient and billing facts to process charges, insurance, and payments."
    },
    {
      "role": "clinician",
      "kinds": [
        "patient_identity",
        "care_team_assignment",
        "clinical_notes",
        "diagnoses",
        "medications",
        "lab_results",
        "consent"
      ],
      "reason": "Assigned clinicians need the patient's clinical record, care-team context, and consent status to provide and coordinate care."
    },
    {
      "role": "lab_tech",
      "kinds": [
        "patient_identity",
        "lab_results"
      ],
      "reason": "Lab technicians need patient identity and lab facts to process, match, and report tests."
    },
    {
      "role": "nurse",
      "kinds": [
        "patient_identity",
        "care_team_assignment",
        "clinical_notes",
        "diagnoses",
        "medications",
        "lab_results"
      ],
      "reason": "Assigned nurses need the patient's clinical record and care-team context to deliver safe day-to-day care."
    },
    {
      "role": "pharmacist",
      "kinds": [
        "patient_identity",
        "medications",
        "diagnoses",
        "lab_results"
      ],
      "reason": "Assigned pharmacists need medication, diagnosis, and relevant lab facts to verify and dispense medicines safely."
    },
    {
      "role": "reception",
      "kinds": [
        "patient_identity",
        "appointments"
      ],
      "reason": "Reception staff need patient identity and appointment facts to check patients in, out, and answer visit-status questions."
    },
    {
      "role": "scheduler",
      "kinds": [
        "patient_identity",
        "appointments"
      ],
      "reason": "Schedulers need patient identity and appointment facts to book, change, or cancel visits."
    },
    {
      "role": "social_worker",
      "kinds": [
        "patient_identity",
        "social_context",
        "family_contact",
        "consent",
        "summary"
      ],
      "reason": "Social workers need social, family, consent, and summary facts to support the patient and manage family communication."
    }
  ],
  "authorities": {
    "roles": [
      "clinician"
    ],
    "reason": "The assigned clinician is the responsible professional for the patient's care and information, so they can approve, restrict, or request deletion."
  }
}
